                offset = r - src_row

                if offset % 2 == 0:
                    # Keep original column
                    output[r][c] = value

                if offset % 2 == 1:
                    # Side columns get the value
                    for dc in [0, 0]:  # column doesn't shift
                        output[r][c] = value
                        break
                else:
                    # even offsets: column is exactly c
                    output[r][c] = value

    # Clean: for odd offsets we need shifted columns
    rebuilt = [[bg] * w for _ in range(h)]
    for c in range(w):
        value = src_val_at_col.get(c, bg)
