    h, w = len(grid), len(grid[0])

    src_row = -1
    src_col = -1
    src_val = bg

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                src_row = r
                src_col = c
                src_val = grid[r][c]
                break
        if src_row >= 0:
